// ── TRASH (soft delete) ──────────────────────────────────────────────────
// Deleted items are snapshotted here instead of being destroyed, so they
// can be restored later. Persisted alongside the rest of the library.
var nbTrash=[];

function nbUpdateTrashBadge(){
  var badge=document.getElementById('nb-trash-count-nav');
  if(!badge) return;
  if(nbTrash.length){ badge.textContent=nbTrash.length; badge.style.display='inline-block'; }
  else{ badge.style.display='none'; }
}

function nbConfirmDeleteDoc(docId,topicTitle){
  nbConfirmDelete(topicTitle,function(){
    var doc=window.dynamicDocs[docId];
    // The item keeps its own topic links (doc.topicIds); the topics stay in
    // the library. Snapshots of the topics are kept in case they're gone by
    // the time the item is restored.
    var linkedTopics=doc?TOPICS.filter(function(x){return doc.topicIds.indexOf(x.id)!==-1;}):[];
    nbTrash.push({
      trashId:'trash-'+Date.now()+'-'+Math.floor(Math.random()*10000),
      type:'doc',
      docId:docId,
      doc:doc?JSON.parse(JSON.stringify(doc)):null,
      topicSnapshots:JSON.parse(JSON.stringify(linkedTopics)),
      title:topicTitle,
      deletedAt:Date.now()
    });
    delete window.dynamicDocs[docId];
    nbRenderSidebar();
    renderLibrary(nbCurrentLibCat||'all');
    if(linkedTopics.length) nbOpenTopic(linkedTopics[0].id); else showView('library');
    nbSaveLibrary('נמחק: '+topicTitle);
    nbUpdateTrashBadge();
  });
}

// Handles delete clicks from any card — active items with a real doc behind
// them go through nbConfirmDeleteDoc; placeholder (non-active) topics that
// have no content yet are simply removed from the list.
function nbConfirmDeleteTopic(topicId){
  var t=TOPICS.find(function(x){return x.id===topicId;});
  if(!t) return;
  var items=nbTopicItems(t.id);
  if(items.length){
    nbConfirmGeneric('לא ניתן למחוק את הנושא',
      'בנושא <strong style="color:var(--navy)">'+t.title+'</strong> יש '+items.length+' פריטי ידע. כדי לא לאבד ידע, יש למחוק את הפריטים או לשייך אותם לנושא אחר לפני מחיקת הנושא.',
      'פתח את הנושא','var(--navy)',function(){ nbOpenTopic(t.id); });
    return;
  }
  nbConfirmDelete(t.title,function(){
    nbTrash.push({
      trashId:'trash-'+Date.now()+'-'+Math.floor(Math.random()*10000),
      type:'topic',
      doc:null,
      topicSnapshot:JSON.parse(JSON.stringify(t)),
      wasPlaceholderTopic:true,
      title:t.title,
      deletedAt:Date.now()
    });
    var idx=TOPICS.indexOf(t);
    if(idx>-1) TOPICS.splice(idx,1);
    nbRenderSidebar();
    renderLibrary(nbCurrentLibCat||'all');
    nbSaveLibrary('נמחק: '+t.title);
    nbUpdateTrashBadge();
  });
}

function nbRestoreFromTrash(trashId){
  var idx=nbTrash.findIndex(function(x){return x.trashId===trashId;});
  if(idx===-1) return;
  var entry=nbTrash[idx];
  if(entry.type==='doc'&&entry.doc){
    window.dynamicDocs=window.dynamicDocs||{};
    var doc=entry.doc;
    var snapshots=(entry.topicSnapshots&&entry.topicSnapshots.length)?entry.topicSnapshots:(entry.topicSnapshot?[entry.topicSnapshot]:[]);
    // Items deleted before the restructure have no topicIds of their own.
    if(!doc.topicIds||!doc.topicIds.length) doc.topicIds=snapshots.map(function(s){return s.id;});
    // Bring back any of its topics that were deleted in the meantime.
    snapshots.forEach(function(snap){
      if(!TOPICS.some(function(x){return x.id===snap.id;})) TOPICS.push(JSON.parse(JSON.stringify(snap)));
    });
    window.dynamicDocs[entry.docId]=doc;
    nbNormalizeModel();
  } else if(entry.type==='topic'&&entry.topicSnapshot){
    if(!TOPICS.some(function(x){return x.id===entry.topicSnapshot.id;})) TOPICS.push(entry.topicSnapshot);
    nbNormalizeModel();
  }
  nbTrash.splice(idx,1);
  nbRenderSidebar();
  renderLibrary(nbCurrentLibCat||'all');
  nbSaveLibrary('שוחזר מסל מיחזור: '+entry.title);
  nbUpdateTrashBadge();
  nbOpenTrash();
}

function nbPermanentlyDeleteFromTrash(trashId){
  var idx=nbTrash.findIndex(function(x){return x.trashId===trashId;});
  if(idx===-1) return;
  if(nbWasPublished(nbTrash[idx].doc)) return; // spec §10: published items are kept for history
  nbTrash.splice(idx,1);
  nbSaveLibrary('נמחק לצמיתות מסל המיחזור');
  nbUpdateTrashBadge();
  nbOpenTrash();
}

function nbOpenTrash(){
  var existing=document.getElementById('nb-trash-overlay');
  if(existing) existing.remove();

  var overlay=document.createElement('div');
  overlay.id='nb-trash-overlay';
  overlay.style.cssText='position:fixed;inset:0;background:rgba(0,0,0,.45);z-index:9999;display:flex;align-items:center;justify-content:center;padding:20px';

  var modal=document.createElement('div');
  modal.style.cssText='background:#fff;border-radius:16px;padding:22px;max-width:480px;width:100%;max-height:80vh;overflow-y:auto;font-family:Rubik,sans-serif;direction:rtl';

  var head=document.createElement('div');
  head.style.cssText='display:flex;align-items:center;justify-content:space-between;margin-bottom:14px;padding-bottom:12px;border-bottom:1px solid var(--border)';
  head.innerHTML='<div style="font-size:16px;font-weight:700;color:var(--navy)">🗑️ סל מיחזור</div>';

  var headBtns=document.createElement('div');
  headBtns.style.cssText='display:flex;align-items:center;gap:4px';

  var historyBtn=document.createElement('button');
  historyBtn.textContent='🕓 היסטוריה';
  historyBtn.style.cssText='background:none;border:1px solid var(--border);border-radius:20px;font-size:11.5px;color:var(--muted);cursor:pointer;padding:5px 10px;font-family:Rubik,sans-serif';
  historyBtn.addEventListener('click',function(){ overlay.remove(); nbOpenHistory(); });
  headBtns.appendChild(historyBtn);

  var closeBtn=document.createElement('button');
  closeBtn.textContent='✕';
  closeBtn.style.cssText='background:none;border:none;font-size:16px;color:var(--muted);cursor:pointer;padding:4px 8px';
  closeBtn.addEventListener('click',function(){ overlay.remove(); });
  headBtns.appendChild(closeBtn);
  head.appendChild(headBtns);

  var list=document.createElement('div');
  if(!nbTrash.length){
    list.innerHTML='<div style="text-align:center;color:var(--muted);font-size:13.5px;padding:30px 10px">סל המיחזור ריק</div>';
  } else {
    list.innerHTML=nbTrash.slice().reverse().map(function(entry){
      var d=new Date(entry.deletedAt);
      var dateStr=d.toLocaleDateString('he-IL')+' '+d.toLocaleTimeString('he-IL',{hour:'2-digit',minute:'2-digit'});
      return '<div style="display:flex;align-items:center;justify-content:space-between;gap:10px;padding:10px 4px;border-bottom:1px solid var(--border)">'
        +'<div style="min-width:0"><div style="font-size:13.5px;font-weight:600;color:var(--text);white-space:nowrap;overflow:hidden;text-overflow:ellipsis">'+entry.title+'</div>'
        +'<div style="font-size:11.5px;color:var(--muted);margin-top:2px">נמחק ב-'+dateStr+'</div></div>'
        +'<div style="display:flex;gap:6px;flex-shrink:0">'
        +'<button onclick="nbRestoreFromTrash(\''+entry.trashId+'\')" style="height:32px;padding:0 12px;background:var(--navy);color:#fff;border:none;border-radius:7px;font-size:12.5px;font-weight:600;cursor:pointer;font-family:Rubik,sans-serif">↩️ שחזר</button>'
        +(nbWasPublished(entry.doc)
          ?'<span title="פריט שפורסם לא נמחק לצמיתות. אפשר לשחזר אותו ולהעביר לסטטוס \'ארכיון\' או \'לא בתוקף\'" style="font-size:11px;color:var(--muted);align-self:center;max-width:110px;line-height:1.3">פורסם בעבר — נשמר לתיעוד</span>'
          :'<button onclick="nbPermanentlyDeleteFromTrash(\''+entry.trashId+'\')" style="height:32px;padding:0 12px;background:#fff;color:var(--red);border:1.5px solid var(--red);border-radius:7px;font-size:12.5px;font-weight:600;cursor:pointer;font-family:Rubik,sans-serif">מחק לצמיתות</button>')
        +'</div></div>';
    }).join('');
  }

  modal.appendChild(head);
  modal.appendChild(list);
  overlay.appendChild(modal);
  overlay.addEventListener('click',function(e){ if(e.target===overlay) overlay.remove(); });
  document.body.appendChild(overlay);
}

function nbEditDoc(docId){
  try{
    nbEditDocImpl(docId);
  }catch(e){
    console.error('nbEditDoc failed:', e);
    alert('אירעה שגיאה בפתיחת פריט הידע לעריכה: '+e.message+'\n\nנסה לרענן את הדף (ייתכן שנטענת גרסה ישנה מהמטמון של הדפדפן).');
  }
}

function nbEditDocImpl(docId){
  var doc=window.dynamicDocs[docId];
  if(!doc) return;

  // Reset form state
  NB_STAGES.forEach(function(s){ nbState[s.id]={picked:[],custom:[],applied:false,s1data:{}}; }); nbState._bodies={};
  nbCustomStages=[];
  nbStageOrder=['s1'];

  // Restore s1 data
  nbState['s1'].s1data={topic:doc.topic,desc:doc.desc||'',kind:doc.kind,worlds:(doc.worlds||[]).slice(),
    tags:(doc.tags||[]).join(', '),owner:doc.owner||'',topicId:doc.topicIds&&doc.topicIds.length?String(doc.topicIds[0]):'',cat:doc.cat,
    status:doc.status,trackState:(doc.track||{}).state||'',trackPriority:(doc.track||{}).priority||'',trackGap:(doc.track||{}).gap||'',trackSource:(doc.track||{}).source||''};
  // Typed items: load their content (or a conversion of their old steps) into the editor.
  nbState._bodies={};
  if(!nbIsStageKind(doc.kind)) nbState._bodies[doc.kind]=nbBodyForEditor(doc);
  nbState['s1'].applied=true;

  // Restore stage selections (rebuilding any custom, user-created stages
  // that don't match one of the fixed NB_STAGES definitions), preserving
  // the order the stages were saved in
  doc.stages.forEach(function(savedStage){
    // Only a stable stage id is trustworthy for matching. "num" alone is NOT
    // reliable: built-in knowledge items number their own content stages
    // starting at "1", which would otherwise collide with Stage 1's num
    // ("1") and duplicate the identification-fields stage on every edit.
    var def=savedStage.id ? NB_STAGES.filter(function(x){return x.id===savedStage.id;})[0] : null;
    if(!def){
      nbCustomStageSeq++;
      var newId=savedStage.id||('cs'+nbCustomStageSeq);
      def={id:newId,num:savedStage.num,req:false,title:savedStage.title,sub:'שלב מותאם אישית',options:[],ph:'הקלד שאלה / פריט...',custom_stage:true};
      nbCustomStages.push(def);
      nbState[def.id]={picked:[],custom:[],applied:false,s1data:{},images:{}};
    }
    nbStageOrder.push(def.id);
    savedStage.items.forEach(function(item){
      var txt=typeof item==='object'?item.text:item;
      var img=typeof item==='object'?item.img:null;
      var optIdx=def.options?def.options.findIndex(function(o){return o.text===txt;}):-1;
      if(optIdx>=0){
        nbState[def.id].picked.push(optIdx);
        if(img){if(!nbState[def.id].images)nbState[def.id].images={};nbState[def.id].images[optIdx]=img;}
      } else {
        nbState[def.id].custom.push(txt);
      }
    });
    if(nbState[def.id].picked.length+nbState[def.id].custom.length>0)
      nbState[def.id].applied=true;
  });

  // Store docId being edited
  window.nbEditingDocId=docId;

  showView('new');
  nbRender();

  // Scroll to top
  window.scrollTo(0,0);

  // Change the "צור" button label to "עדכן"
  setTimeout(function(){
    var sumBox=document.getElementById('nb-summary');
    if(sumBox){
      var createBtn=sumBox.querySelector('button');
      if(createBtn) createBtn.textContent='💾 שמור שינויים';
    }
    nbUpdateSummary();
  }, 100);
}

function catLabel(cat){
  var m={sim:SIM_ICON+' SIM/eSIM',tech:'🔧 טכני',tech2:'🔧 טכני',billing:'💳 חיובים',plans:'📋 מסלולים',intl:'✈️ חו"ל',ops:'🎧 שיחה'};
  return m[cat]||'📄 כללי';
}

function nbExport(){
  var out={};
  nbGetStageOrder().forEach(function(sid){
    if(!nbState[sid].applied) return;
    var def=nbGetAllStages().filter(function(x){return x.id===sid;})[0];
    if(!def) return;
    var st=nbState[sid];
    out['שלב '+nbContentNum(sid)+' – '+def.title]=sid==='s1'?st.s1data:st.picked.map(function(i){return def.options[i].text;}).concat(st.custom);
  });
  var a=document.createElement('a');
  a.href=URL.createObjectURL(new Blob([JSON.stringify(out,null,2)],{type:'application/json'}));
  a.download='תדריך-חדש.json';a.click();
}

function nbInit(){
  NB_STAGES.forEach(function(s){nbState[s.id]={picked:[],custom:[],applied:false,s1data:{},images:{}};}); nbState._bodies={};
  nbCustomStages=[];
  nbStageOrder=[];
  nbRender();
}

function nbGoNew(){ showView('new'); }

function initObservers(){
  // event delegation for dynamically created buttons
  document.addEventListener('click', function(e){
    var btn=e.target.closest('[data-action="new"]');if(btn) showView('new');
  });

  var obs=new IntersectionObserver(function(entries){
    entries.forEach(function(e){
      if(e.isIntersecting){
        e.target.querySelectorAll('.fade-in:not(.visible)').forEach(function(el,i){setTimeout(function(){el.classList.add('visible')},i*55)});
        obs.unobserve(e.target);
      }
    });
  },{threshold:0.05});
  document.querySelectorAll('.view').forEach(function(v){obs.observe(v)});
}

