// ── CUSTOM (USER-CREATED) STAGES ────────────────────────────────────────
// Lets the person building a knowledge item add a brand-new stage from
// scratch (title + subtitle) and then type its sub-inquiries manually,
// exactly like the "הוסף ידנית" flow on the built-in stages.
var nbCustomStages=[];
var nbCustomStageSeq=0;
function nbGetAllStages(){ return NB_STAGES.concat(nbCustomStages); }

function nbAddCustomStage(){
  var titleInp=document.getElementById('nb-newstage-title');
  var subInp=document.getElementById('nb-newstage-sub');
  var reqInp=document.getElementById('nb-newstage-req');
  var title=(titleInp&&titleInp.value.trim())||'';
  if(!title){ if(titleInp) titleInp.focus(); return; }
  nbCustomStageSeq++;
  var id='cs'+nbCustomStageSeq;
  var num=String(NB_STAGES.length+nbCustomStages.length+1);
  var sub=(subInp&&subInp.value.trim())||'שלב מותאם אישית';
  var req=!!(reqInp&&reqInp.checked);
  var stage={id:id,num:num,req:req,title:title,sub:sub,options:[],ph:'הקלד שאלה / פריט...',custom_stage:true};
  nbCustomStages.push(stage);
  nbState[id]={picked:[],custom:[],applied:false,s1data:{},images:{}};
  titleInp.value='';
  if(subInp) subInp.value='';
  if(reqInp) reqInp.checked=false;
  nbRender();
  var el=document.getElementById('nb-stage-'+id);
  if(el){ el.classList.add('open'); el.scrollIntoView({behavior:'smooth',block:'nearest'}); }
}

function nbRemoveCustomStage(id){
  nbCustomStages=nbCustomStages.filter(function(s){return s.id!==id;});
  delete nbState[id];
  nbRender();
}

// ── DRAG-TO-REORDER STAGES ───────────────────────────────────────────────
var nbStageOrder=[];

function nbGetStageOrder(){
  var allIds=nbGetAllStages().map(function(s){return s.id;});
  var seen={};
  // De-dupe defensively: a stale/corrupted saved order (e.g. from an older
  // version of this file, or a previous bug) must never render a stage twice.
  var order=(nbStageOrder||[]).filter(function(id){
    if(seen[id]||allIds.indexOf(id)===-1) return false;
    seen[id]=true;
    return true;
  });
  allIds.forEach(function(id){ if(order.indexOf(id)===-1) order.push(id); });
  nbStageOrder=order;
  return order;
}

// Renumbers stages according to their current drag order. Stage 1 (the
// identification fields) is always "1"; the rest are numbered 2..N by
// their position among each other, regardless of where s1 physically sits.
// Used for the BUILDER's own UI (badges, apply button, summary headings).
function nbDisplayNum(sid){
  if(sid==='s1') return '1';
  var contentOrder=nbGetStageOrder().filter(function(id){return id!=='s1';});
  var idx=contentOrder.indexOf(sid);
  return String(idx>=0?idx+2:'?');
}

// Numbers only the CONTENT stages, 1..N with no gap. Stage 1 is never a
// step in the finished document (it's just identifying metadata), so the
// saved/exported document should start its step numbering at 1 — not 2 —
// or it looks like the first step is missing.
function nbContentNum(sid){
  var contentOrder=nbGetStageOrder().filter(function(id){return id!=='s1';});
  var idx=contentOrder.indexOf(sid);
  return String(idx>=0?idx+1:'?');
}

// Pointer-based drag (works with mouse AND touch, unlike native HTML5 DnD)
var nbDragState=null;

function nbStageHandlePointerDown(e,sid){
  e.preventDefault();
  var section=document.getElementById('nb-stage-'+sid);
  var container=document.getElementById('nb-stages');
  if(!section||!container) return;
  try{ e.target.setPointerCapture(e.pointerId); }catch(err){}
  var rect=section.getBoundingClientRect();
  var placeholder=document.createElement('div');
  placeholder.className='stage-drag-placeholder';
  placeholder.style.height=rect.height+'px';
  section.parentNode.insertBefore(placeholder,section);
  section.style.position='fixed';
  section.style.zIndex='999';
  section.style.width=rect.width+'px';
  section.style.left=rect.left+'px';
  section.style.top=rect.top+'px';
  section.style.pointerEvents='none';
  section.classList.add('dragging');
  document.body.style.userSelect='none';
  nbDragState={sid:sid,section:section,placeholder:placeholder,container:container,offsetY:e.clientY-rect.top,offsetX:e.clientX-rect.left};
  document.addEventListener('pointermove',nbStageHandlePointerMove);
  document.addEventListener('pointerup',nbStageHandlePointerUp);
  document.addEventListener('pointercancel',nbStageHandlePointerUp);
}

function nbStageHandlePointerMove(e){
  var d=nbDragState;
  if(!d) return;
  d.section.style.top=(e.clientY-d.offsetY)+'px';
  d.section.style.left=(e.clientX-d.offsetX)+'px';
  var siblings=Array.prototype.slice.call(d.container.querySelectorAll('.acc-section')).filter(function(el){return el!==d.section;});
  var placed=false;
  for(var i=0;i<siblings.length;i++){
    var sRect=siblings[i].getBoundingClientRect();
    var sMid=sRect.top+sRect.height/2;
    if(e.clientY<sMid){
      siblings[i].parentNode.insertBefore(d.placeholder,siblings[i]);
      placed=true;
      break;
    }
  }
  if(!placed && siblings.length){
    var last=siblings[siblings.length-1];
    last.parentNode.insertBefore(d.placeholder,last.nextSibling);
  }
}

function nbStageHandlePointerUp(){
  var d=nbDragState;
  document.removeEventListener('pointermove',nbStageHandlePointerMove);
  document.removeEventListener('pointerup',nbStageHandlePointerUp);
  document.removeEventListener('pointercancel',nbStageHandlePointerUp);
  document.body.style.userSelect='';
  if(!d) return;
  d.placeholder.parentNode.insertBefore(d.section,d.placeholder);
  d.placeholder.remove();
  d.section.style.position='';
  d.section.style.zIndex='';
  d.section.style.width='';
  d.section.style.left='';
  d.section.style.top='';
  d.section.style.pointerEvents='';
  d.section.classList.remove('dragging');
  var newOrder=Array.prototype.map.call(d.container.querySelectorAll('.acc-section'),function(el){return el.id.replace('nb-stage-','');});
  nbStageOrder=newOrder;
  nbDragState=null;
  nbRender();
}

function nbRenderAddStageForm(){
  return '<div style="background:var(--white);border:1.5px dashed var(--border-strong);border-radius:var(--r);padding:14px;margin-top:6px">'
    +'<div style="font-size:12.5px;font-weight:700;color:var(--navy);margin-bottom:9px">➕ הוסף שלב חדש משלך</div>'
    +'<div style="display:flex;flex-direction:column;gap:8px">'
    +'<input type="text" id="nb-newstage-title" placeholder="שם השלב (לדוגמה: בדיקת חבילת רומינג)" style="height:36px;padding:0 10px;font-size:13px;border:1.5px solid var(--border);border-radius:var(--rs);background:var(--input-bg);color:var(--text);outline:none;font-family:Rubik,sans-serif;direction:rtl">'
    +'<input type="text" id="nb-newstage-sub" placeholder="תת-כותרת (אופציונלי)" style="height:34px;padding:0 10px;font-size:12.5px;border:1.5px solid var(--border);border-radius:var(--rs);background:var(--input-bg);color:var(--text);outline:none;font-family:Rubik,sans-serif;direction:rtl">'
    +'<div style="display:flex;align-items:center;justify-content:space-between;gap:8px">'
    +'<label style="display:inline-flex;align-items:center;gap:6px;font-size:12.5px;color:var(--text-2);cursor:pointer"><input type="checkbox" id="nb-newstage-req" style="accent-color:var(--red);width:14px;height:14px">שלב חובה</label>'
    +'<button onclick="nbAddCustomStage()" style="height:34px;padding:0 16px;background:var(--navy);color:#fff;border:none;border-radius:var(--rs);font-size:13px;font-weight:600;cursor:pointer;font-family:Rubik,sans-serif">✚ צור שלב</button>'
    +'</div></div></div>';
}

var nbState={};
NB_STAGES.forEach(function(s){nbState[s.id]={picked:[],custom:[],applied:false,s1data:{}};}); nbState._bodies={};

function nbRender(){
  var el=document.getElementById('nb-stages');
  if(!el) return;
  var order=nbGetStageOrder();
  var allStages=nbGetAllStages();
  var orderedStages=order.map(function(id){return allStages.filter(function(s){return s.id===id;})[0];}).filter(Boolean);
  // R and S use the step builder; every other type gets its own editor.
  if(!nbIsStageKind(nbCurKind())){
    var s1def=allStages.filter(function(s){return s.id==='s1';})[0];
    el.innerHTML=nbRenderStage(s1def)+'<div id="nb-kind-editor" class="kind-editor">'+nbKindEditorHTML(nbCurKind())+'</div>';
    nbUpdateSummary();
    nbSaveDraft();
    return;
  }
  el.innerHTML=orderedStages.map(nbRenderStage).join('')+nbRenderAddStageForm();
  // Update summary
  nbUpdateSummary();
  nbSaveDraft();
  // Restore image previews from nbState
  nbGetAllStages().forEach(function(s){
    var st=nbState[s.id];
    if(!st||!st.images) return;
    Object.keys(st.images).forEach(function(k){
      var dataUrl=st.images[k];
      var key=parseInt(k);
      if(!isNaN(key)){
        // Option-level image
        var uid='nb-opt-'+s.id+'-'+k;
        var container=document.getElementById('nb-opt-imgs-'+uid);
        if(container && container.children.length===0){
          var wrap=document.createElement('div');
          wrap.style.cssText='position:relative;display:inline-block;margin-top:8px';
          var img=document.createElement('img');
          img.src=dataUrl;
          img.style.cssText='max-width:100%;max-height:180px;width:auto;border-radius:6px;border:1px solid var(--border);display:block';
          nbMakeZoomable(img);
          var del=document.createElement('button');
          del.textContent='×';
          del.style.cssText='position:absolute;top:2px;right:2px;background:var(--red);color:#fff;border:none;border-radius:50%;width:18px;height:18px;font-size:12px;cursor:pointer;line-height:18px;padding:0;text-align:center';
          (function(sid,kk){del.addEventListener('click',function(e){e.stopPropagation();delete nbState[sid].images[kk];wrap.remove();});})(s.id,k);
          wrap.appendChild(img);wrap.appendChild(del);
          container.appendChild(wrap);
        }
      }
    });
  });
}

